a<-commandArgs(TRUE);p<-a[1];w<-read.csv(gzfile('dev/data/policy-factorial/results/windows.csv.gz'));x<-subset(w,ploidy==1 & food_rate %in% c(.05,.025) & hi %in% c(800,1000));g<-split(x,paste(x$food_rate,x$age_mode,x$seed,x$hi));b<-do.call(rbind,lapply(g,function(z){z<-z[order(z$mono),];stopifnot(all(z$mono==0:8));data.frame(food_rate=z$food_rate[1],age_mode=z$age_mode[1],seed=z$seed[1],tick=z$hi[1],delta=z$nend[1]-mean(z$nend[-1]))}));s<-aggregate(delta~food_rate+age_mode+tick,b,mean);write.csv(s,file.path(p,'prior-reference.csv'),row.names=FALSE);print(s)
